<script setup lang="ts">
import { computed } from "vue";
import StatePanel from "../../components/ui/StatePanel.vue";
import { usePaperCenter } from "../../composables/usePaperCenter";

const { actionMessage, addPaper, continueTask, data, error, filteredTasks, load, loading, openActivityTarget, query, stageLabels, updateQuery } = usePaperCenter();
const stages = ["problem_definition", "literature_reading", "paper_understanding", "evidence_organization", "conclusion_formation"] as const;
const recentTasks = computed(() => filteredTasks.value.slice(0, 3));
const visibleActivities = computed(() => data.value?.recent_activities.slice(0, 5) ?? []);
const visiblePapers = computed(() => data.value?.recent_papers.slice(0, 5) ?? []);
const summaryItems = computed(() => data.value ? [
  { label: "研究论文", value: data.value.summary.papers, tone: "blue", icon: "▤" },
  { label: "阅读中", value: data.value.summary.reading, tone: "green", icon: "▱" },
  { label: "精读中", value: data.value.summary.deep_reading, tone: "violet", icon: "◇" },
  { label: "已完成", value: data.value.summary.completed, tone: "orange", icon: "✓" },
  { label: "待确认", value: data.value.summary.pending_confirmation_items, tone: "slate", icon: "⌛" },
] : []);
function formatDate(value: string | null): string { return value ? new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value)) : "暂无记录"; }
function taskProgressLabel(task: (typeof recentTasks.value)[number]): string { return task.work_mode === "deep_reading" && task.analysis_total > 0 ? "精读进度 " + task.analysis_completed + " / " + task.analysis_total : task.current_section ? "阅读至 " + task.current_section : task.reading_progress_percent + "% 阅读进度"; }
function taskButtonLabel(task: (typeof recentTasks.value)[number]): string { return task.work_mode === "deep_reading" ? "继续精读" : task.next_action.title; }
function statusLabel(status: string): string { return { reading: "阅读中", unread: "待阅读", deep_reading: "精读中", completed: "已完成", pending: "待确认" }[status] ?? status; }
</script>

<template>
  <main class="paper-center" data-testid="paper-center-layout">
    <header class="page-header">
      <div class="title-block"><p class="page-eyebrow">研究进度展览台</p><h1 class="page-title">论文中心</h1><p class="page-subtitle">查看论文研究进度，继续最近的科研工作</p></div>
      <div class="header-actions">
        <label class="search-field" for="center-search"><span class="search-icon" aria-hidden="true">⌕</span><span class="sr-only">搜索研究论文、作者、关键词</span><input id="center-search" aria-label="搜索研究论文、作者、关键词" :value="query" placeholder="搜索研究论文、作者、关键词…" @input="updateQuery(($event.target as HTMLInputElement).value)"></label>
        <button class="add-button" data-testid="add-paper" type="button" @click="addPaper"><span aria-hidden="true">＋</span>添加论文</button>
      </div>
    </header>
    <p class="live-region" aria-live="polite">{{ loading ? "正在加载论文中心" : actionMessage }}</p>
    <StatePanel v-if="loading" title="正在加载研究进度" description="正在读取当前研究、任务和统计。" />
    <StatePanel v-else-if="error" title="论文中心暂时不可用" :description="error"><button type="button" @click="load">重试</button></StatePanel>
    <template v-else-if="data">
      <section class="panel research-panel" data-testid="current-research" aria-labelledby="current-research-title">
        <div class="panel-heading">
          <div><p class="section-kicker">当前研究</p><h2 id="current-research-title" class="research-title">{{ data.current_research?.research_name ?? "尚未选择当前研究" }}</h2><p class="research-question">{{ data.current_research ? "研究问题由当前研究上下文维护；请从研究工作台继续完善。" : "选择一个研究项目后，这里会显示研究阶段与关联论文进度。" }}</p></div>
          <RouterLink class="details-link" to="/paper-research">查看研究详情 <span aria-hidden="true">›</span></RouterLink>
        </div>
        <div v-if="data.current_research" class="research-facts"><span><i aria-hidden="true">☷</i>当前阶段：<b>{{ stageLabels[data.current_research.stage] }}</b></span><span><i aria-hidden="true">▧</i>关联论文：<b>{{ data.summary.papers }} 篇</b></span><span><i aria-hidden="true">◷</i>最近活动：<b>{{ formatDate(visibleActivities[0]?.occurred_at ?? null) }}</b></span></div>
        <div v-if="data.current_research" class="stage-rail" aria-label="研究阶段">
          <div v-for="(stage, index) in stages" :key="stage" class="stage-item" :class="{ complete: stages.indexOf(data.current_research.stage) > index, current: data.current_research.stage === stage }"><span class="stage-number">{{ stages.indexOf(data.current_research.stage) > index ? "✓" : index + 1 }}</span><b>{{ stageLabels[stage] }}</b></div>
        </div>
      </section>

      <section class="panel continue-panel" data-testid="continue-research" aria-labelledby="continue-research-title">
        <div class="panel-heading continue-heading"><div><p class="section-kicker">继续研究</p><h2 id="continue-research-title" class="section-title">从上次停下的地方继续</h2></div><span class="task-count">{{ recentTasks.length }} 项待继续任务</span></div>
        <div v-if="!recentTasks.length" class="empty-state"><span class="empty-icon" aria-hidden="true">▤</span><p>暂无匹配的研究任务</p><RouterLink to="/papers">前往论文库添加论文</RouterLink></div>
        <ol v-else class="task-list">
          <li v-for="(task, index) in recentTasks" :key="task.paper_item_id" class="task-row" :class="{ 'task-primary': index === 0 }">
            <div class="paper-preview" aria-hidden="true"><span class="preview-rule preview-title"></span><span class="preview-rule"></span><span class="preview-rule short"></span><span class="preview-grid"></span><span class="preview-rule"></span></div>
            <div class="task-rank" :class="{ secondary: index > 0 }">{{ index + 1 }}</div>
            <div class="task-content"><h3 :title="task.title ?? undefined">{{ task.title ?? "未命名论文" }}</h3><p class="citation">{{ task.journal ?? "期刊信息待补充" }} · {{ task.year ?? "年份未知" }}</p><p class="progress-copy">{{ taskProgressLabel(task) }}</p><div class="progress-track" :aria-label="'阅读进度 ' + task.reading_progress_percent + '%'" role="progressbar" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="task.reading_progress_percent"><span :style="{ width: task.reading_progress_percent + '%' }"></span></div></div>
            <div class="next-step"><p class="next-step-label"><span aria-hidden="true">☷</span>下一步</p><p>{{ task.next_action.description }}</p></div>
            <button class="continue-button" data-testid="continue-action" type="button" :class="{ secondary: index > 0 }" :disabled="!task.next_action.is_available" @click="continueTask(task)">{{ taskButtonLabel(task) }}</button>
          </li>
        </ol>
      </section>

      <div class="bottom-grid">
        <section class="panel activity-panel" data-testid="recent-activity" aria-labelledby="activity-title">
          <div class="compact-heading"><h2 id="activity-title" class="section-title">近期研究动态</h2></div>
          <ol v-if="visibleActivities.length" class="activity-list"><li v-for="activity in visibleActivities" :key="activity.id"><span class="activity-marker" :class="{ muted: !activity.target_available }" aria-hidden="true"></span><time>{{ formatDate(activity.occurred_at) }}</time><div class="activity-copy"><b>{{ activity.summary ?? activity.kind }}</b><span>{{ activity.paper_title ?? "论文" }}</span></div><button class="row-link" type="button" :disabled="!activity.target_available" @click="openActivityTarget(activity)">{{ activity.target_available ? "回到位置" : "暂不可回跳" }}</button></li></ol>
          <p v-else class="compact-empty">暂无研究动态</p>
        </section>
        <section class="panel recent-paper-panel" aria-labelledby="recent-papers-title">
          <div class="compact-heading"><h2 id="recent-papers-title" class="section-title">最近研究论文</h2><RouterLink class="details-link" to="/papers">查看全部论文 <span aria-hidden="true">›</span></RouterLink></div>
          <ul v-if="visiblePapers.length" class="recent-paper-list"><li v-for="paper in visiblePapers" :key="paper.paper_item_id"><span class="mini-preview" aria-hidden="true"></span><div class="paper-copy"><b :title="paper.title ?? undefined">{{ paper.title ?? "未命名论文" }}</b><span>{{ paper.journal ?? "期刊信息待补充" }} · {{ paper.year ?? "年份未知" }}</span></div><span class="paper-status" :class="paper.reading_status">{{ statusLabel(paper.reading_status) }}</span><RouterLink class="paper-arrow" :to="'/paper-research/' + paper.paper_item_id" :aria-label="'打开 ' + (paper.title ?? '论文')">›</RouterLink></li></ul>
          <p v-else class="compact-empty">暂无论文记录</p>
        </section>
      </div>
      <section class="summary-strip" aria-label="进度概览"><div v-for="item in summaryItems" :key="item.label" class="summary-item"><span class="summary-icon" :class="item.tone" aria-hidden="true">{{ item.icon }}</span><div><span>{{ item.label }}</span><b>{{ item.value }}</b></div></div></section>
    </template>
  </main>
</template>

